"""Print autogenerated .vtt captions as plain de-duplicated text. Usage: python3 -I caption_text.py <file.vtt>..."""
import sys, re, pathlib
for p in sys.argv[1:]:
    lines, prev = [], None
    for l in pathlib.Path(p).read_text().splitlines():
        l=l.strip()
        if not l or l=="WEBVTT" or "-->" in l or l.isdigit(): continue
        if l!=prev: lines.append(l)
        prev=l
    print(f"\n######## {pathlib.Path(p).name}\n" + " ".join(lines))
